# SPDX-License-Identifier: BSD-3-Clause
"""Generate the CLI reference page from ``arrayprobe.cli``'s own parser.

Plan S4C ("Reference (generated): ... CLI reference"). Every subcommand's
help text is generated by argparse from the same ``add_argument`` calls the
CLI actually runs on, so this page cannot describe a flag that does not
exist or omit one that does -- the failure mode ``tests/test_tool_usage_matches_parser.py``
polices for ``scripts/`` scripts, applied here to the one real console entry
point instead.

The count is deliberately not written here. This docstring said "the five
subcommands" until 2026-09-10, by which point there were ten -- a typed
number in prose goes stale exactly the way the counts this repository
propagates mechanically do, and a docstring cannot read a registry. The
generator walks whatever the parser declares, so naming no number is both
shorter and true.

Needs the venv (imports ``arrayprobe``), unlike ``build.py``'s stdlib-only
render -- run this first, then ``build.py``, exactly as its own docstring
already documents for ``apidoc.py``.

Usage, from the repository root::

    .venv/Scripts/python.exe docs/_build/clidoc.py [--public] [--check]

``--public`` writes the page's release twin (``.public`` before the suffix), which the release
builder ships under the page's own name; a tree without the v3.1.4 engine needs no
``--public``. The public build carries no v3.1.4 engine, so the parser is built as if that
engine were absent: the help text then offers only the engines a public install has. Doc
tooling only; the CLI's behaviour is unchanged.
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
PAGE = ROOT.parent / "13-cli-reference.md"
PUBLIC_PAGE = PAGE.with_name(PAGE.stem + ".public" + PAGE.suffix)

#: The Python whose argparse printed the page. argparse's help layout changes between minor
#: versions (3.13 prints ``-o, --out OUT`` where 3.12 prints ``-o OUT, --out OUT``), so the page
#: is byte-comparable only on the version that wrote it: CI's 3.13 leg reported a page generated
#: on 3.12 as stale (2026-10-01). The page records it; ``--check`` compares on that version and
#: says so, exit VERSION_MISMATCH, on any other.
PY = f"{sys.version_info.major}.{sys.version_info.minor}"
VERSION_MISMATCH = 5
_MARKER = ("<!-- argparse help as printed by Python {}; "
           "clidoc.py --check compares on that version -->")

sys.path.insert(0, str(ROOT.parents[1] / "src"))
from arrayprobe import cli  # noqa: E402


def _subcommands(parser: argparse.ArgumentParser) -> list[tuple[str, argparse.ArgumentParser]]:
    """The subparsers in the order they were added, not dict/set order; ``[]`` for a leaf.

    Walks ``_actions`` rather than ``_subparsers``: the latter is set only once
    ``add_subparsers`` has run, so a leaf parser has none to walk."""
    for action in parser._actions:  # noqa: SLF001 -- argparse offers no public walk
        if isinstance(action, argparse._SubParsersAction):
            return list(action.choices.items())
    return []


def _sections(parser: argparse.ArgumentParser, path: tuple[str, ...] = ()
              ) -> list[tuple[tuple[str, ...], argparse.ArgumentParser]]:
    """Every subcommand at every depth, depth-first in the order added.

    Before the nested walk, only the top level was walked, so a nested verb's own flags --
    ``soda2 run --out``, ``validate timing-closure``'s -- appeared nowhere on the page.
    """
    out = []
    for name, sub in _subcommands(parser):
        out.append(((*path, name), sub))
        out.extend(_sections(sub, (*path, name)))
    return out


#: Plain-words groups for the at-a-glance table, in reading order. Presentation only: a
#: subcommand the parser declares but no group names still appears, under "Other commands",
#: and a name here the parser no longer declares is dropped, so the table follows the parser.
GROUPS: list[tuple[str, str, tuple[str, ...]]] = [
    ("Run a whole flight",
     "Start here. One configuration file names every choice; these commands run it, or "
     "re-run one product exactly as it was made.",
     ("run", "soda2", "reprocess")),
    ("Run one stage at a time",
     "The pipeline's steps as separate commands -- decode the raw file, frame particles, "
     "build size distributions, stitch a flight. These run the UIOOPS v3.1.4 engine, the one "
     "that reproduces archived products; `run` uses whichever engine its file names.",
     ("read-binary", "imgproc", "sizedist", "combine", "intarr-threshold", "diode-masks",
      "attributed")),
    ("Inspect and check what was written",
     "Read-only: look at particles, compare two files, or ask what made a product. None of "
     "these changes a number in any file.",
     ("compare", "provenance", "validate", "view", "gallery", "triage")),
    ("Inputs and setup",
     "Make the small inputs a run needs when you do not have them, and see which package "
     "implements what.",
     ("make-demo-flight", "make-tas-file", "tas-from-nasa-ames", "engines")),
]

#: How to read each fenced help block; argparse's own notation, in plain words.
LEGEND = [
    "## How to read this page",
    "",
    "Each command below is shown exactly as `arrayprobe <command> --help` prints it. "
    "In the **usage** line:",
    "",
    "| Notation | Meaning |",
    "|---|---|",
    "| `[ ... ]` | optional -- leave it out and the command still runs |",
    "| no brackets | required -- the command refuses to start without it |",
    "| `UPPERCASE` | a value you supply, e.g. a file path or a number |",
    "| `{a,b}` | pick exactly one of the listed values |",
    "| `raw ...` | one or more of these, separated by spaces |",
    "",
    "**positional arguments** are given in order with no flag in front; **options** start "
    "with `-` or `--`. A flag with no text after it has no further explanation in the "
    "parser. \"Default off\" means the run is unchanged unless you pass the flag.",
    "",
]


#: The "Run one stage at a time" intro for the public page, whose install has no v3.1.4 engine.
PUBLIC_STAGE_INTRO = (
    "Single steps on their own: stitch a flight's size distributions into one product, "
    "compute inter-arrival thresholds, find stuck diodes, write a self-describing product. "
    "`run` runs the whole chain, from the raw file to the stitched flight, on the engine "
    "its configuration file names.")


def _public_parser_patch():
    """Build the parser as a public install sees it: no v3.1.4 engine.

    ``cli`` (and ``driver.run_flight``) read ``_v314_engine_present`` as a module global when
    the parser is built, so rebinding it there is enough. Returns an undo callable."""
    from arrayprobe.driver import run_flight
    saved = [(m, m._v314_engine_present) for m in (cli, run_flight)]  # noqa: SLF001
    for m, _ in saved:
        m._v314_engine_present = lambda: False  # noqa: SLF001

    def undo() -> None:
        for m, f in saved:
            m._v314_engine_present = f  # noqa: SLF001
    return undo


def _help_lines(parser: argparse.ArgumentParser) -> dict[str, str]:
    """Top-level command -> its one-line ``help=`` text, as the parser declares it."""
    for action in parser._actions:  # noqa: SLF001 -- argparse offers no public walk
        if isinstance(action, argparse._SubParsersAction):
            return {a.dest: (a.help or "") for a in action._choices_actions}  # noqa: SLF001
    return {}


def _glance(parser: argparse.ArgumentParser, public: bool = False) -> list[str]:
    """The grouped command table: each group's plain-words intro, then name and summary."""
    helps = _help_lines(parser)
    placed: set[str] = set()
    groups = []
    for title, intro, names in GROUPS:
        if public and title == "Run one stage at a time":
            intro = PUBLIC_STAGE_INTRO
        present = [n for n in names if n in helps]
        placed.update(present)
        if present:
            groups.append((title, intro, present))
    rest = [n for n in helps if n not in placed]
    if rest:
        groups.append(("Other commands", "Commands not yet sorted into a group above.", rest))
    lines = ["## Commands at a glance", ""]
    for title, intro, names in groups:
        lines += [f"**{title}.** {intro}", "", "| Command | What it does |", "|---|---|"]
        for n in names:
            summary = helps[n].replace("|", "\\|")
            lines.append(f"| `{n}` | {summary} |")
        lines.append("")
    return lines


def render(public: bool = False) -> str:
    """The page text; ``public`` builds it as a public install (no v3.1.4 engine) sees it."""
    undo = _public_parser_patch() if public else None
    try:
        return _render(public)
    finally:
        if undo is not None:
            undo()


#: The three per-stage verbs run only the v3.1.4 validation engine, which the public package does
#: not include, so their sections give the v3.5 route instead of help a public install refuses.
_STAGE_VERB_NOTES = {
    verb: ("Not in the public package: this per-stage command runs only the v3.1.4 validation "
           "engine, which the public package does not include. To run " + name + " on v3.5, use "
           '`arrayprobe run <config.toml>` with `[run].engine = "3.5"` and '
           '`[run].stages = "' + stage + '"` (or `"234"` for the whole chain); '
           "`examples/configs/cip_uiops/cip_run.toml` is a template.")
    for verb, (stage, name) in {"read-binary": ("2", "the decode"),
                                "imgproc": ("3", "image processing"),
                                "sizedist": ("4", "the size distribution")}.items()
}


def _render(public: bool) -> str:
    parser = cli.build_parser()
    if not _subcommands(parser):
        raise RuntimeError("build_parser() has no subparsers action")
    lines = [
        "# CLI reference",
        "> Every `arrayprobe` subcommand's help text, generated from the real "
        "parser -- never hand-typed.",
        "",
        "**In short:** one section per subcommand, and one per nested verb "
        "(`soda2 run`, `validate timing-closure`), each a fenced block of "
        "`arrayprobe <command> --help`'s actual output. Regenerate with "
        "`docs/_build/clidoc.py` (needs the venv) whenever a flag changes; "
        "`--check` fails if this page has drifted.",
        "",
        "**See also** [Reference](08-reference.md) · [User guide](02-user-guide.md) "
        "· [Configuration](06-configuration.md).",
        "",
        _MARKER.format(PY),
        "",
        parser.description or "",
        "",
        *_glance(parser, public),
        *LEGEND,
    ]
    for path, sub in _sections(parser):
        lines.append(f"{'#' * (1 + len(path))} `{' '.join(path)}`")
        lines.append("")
        if path and path[0] in _STAGE_VERB_NOTES:
            lines.append(_STAGE_VERB_NOTES[path[0]])
            lines.append("")
            continue
        lines.append("```")
        lines.append(sub.format_help().rstrip())
        lines.append("```")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def recorded_python(page_text: str) -> str | None:
    """The Python version a page's marker line records, or ``None`` if it has none."""
    head, sep, tail = _MARKER.partition("{}")
    for line in page_text.splitlines():
        if line.startswith(head) and line.endswith(tail):
            return line[len(head):len(line) - len(tail)]
    return None


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--check", action="store_true",
                    help="fail if the written page would change, without writing")
    ap.add_argument("--public", action="store_true",
                    help=f"the release page, {PUBLIC_PAGE.name}: built as if no v3.1.4 "
                         "engine were installed")
    args = ap.parse_args(argv)

    page = PUBLIC_PAGE if args.public else PAGE
    flag = " --public" if args.public else ""
    rendered = render(public=args.public)
    if args.check:
        current = page.read_text(encoding="utf-8") if page.is_file() else None
        recorded = recorded_python(current or "")
        if recorded is not None and recorded != PY:
            print(f"NOT COMPARED: {page.name} holds argparse help as printed by Python "
                  f"{recorded}, and this is Python {PY}, whose help layout differs; "
                  f"run --check on {recorded}")
            return VERSION_MISMATCH
        if current != rendered:
            print(f"STALE: {page} does not match arrayprobe.cli.build_parser(); "
                  f"run docs/_build/clidoc.py{flag} to regenerate")
            return 1
        print(f"OK: {page} matches the parser")
        return 0

    page.write_text(rendered, encoding="utf-8")
    print(f"wrote {page}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
